// Benchmark run (SEQUENCESCOPE_SMOKE_MODE=bench, with SEQUENCESCOPE_BACKEND=ts or rust). Times full round trips (request to
// finished result, including transfer and decoding) for the small, medium, and largest alignments and the shuffle test, on
// inputs generated by the seeded PRNG so the Rust-only benchmark (examples/bench.rs) uses exactly the same sequences.
// Memory is measured from outside by tools/bench/measure.py (this page cannot see process memory).
import { createBootstrapWorker, createDistancesWorker, createPairwiseWorker, createShuffleWorker, selectedBackend } from '../backend';
import type { JobWorker } from '../backend';
import { rustAlign, rustBootstrap, rustDistances, rustShuffle } from '../backend/rust';
import type { RustTimings } from '../backend/rust';
import type { BootstrapResult } from '../bio/bootstrap';
import type { AlignRequest, AlignResult, DistanceMatrix, ShuffleRequest, ShuffleSummary } from '../shared/types';
import type { BootstrapRequest, DistancesRequest } from '../workers/protocol';
import { SCENARIOS } from './inputs';
import { bitsHex, fnv1a32, hashTyped, sleep } from './util';

interface ScenarioReport {
  name: string;
  backend: string;
  reps: number;
  runsMs: number[];
  minMs: number;
  medianMs: number;
  checksum: string;
  rust?: { fillMs: number; tracebackMs: number; transferAndDecodeMs: number; frameMB: number };
}

const median = (xs: number[]): number => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)] as number;
const round = (x: number): number => Math.round(x * 10) / 10;

/** A short fingerprint of an alignment result: score, hash of the gapped rows, and hash of the first DP table. */
function alignChecksum(r: AlignResult): string {
  const first = r.dp.kind === 'linear' ? r.dp.H : r.dp.M;
  return `${r.alignment.score}:${fnv1a32(new TextEncoder().encode(r.alignment.rowA + '|' + r.alignment.rowB))}:${hashTyped(first)}:${r.all.length}${r.capped ? '+' : ''}`;
}

/** Runs one alignment on the TypeScript worker and resolves with the result. */
function tsAlign(req: AlignRequest): Promise<AlignResult> {
  return new Promise((resolve, reject) => {
    const w = createPairwiseWorker('ts');
    w.onmessage = (ev) => { if (ev.data.type === 'result') { w.terminate(); resolve(ev.data.value); } else if (ev.data.type === 'error') { w.terminate(); reject(new Error(ev.data.message)); } };
    w.onerror = (ev) => reject(new Error(ev.message));
    w.postMessage(req);
  });
}

/** Runs one shuffle test on the TypeScript worker. */
function tsShuffle(req: ShuffleRequest): Promise<ShuffleSummary> {
  return new Promise((resolve, reject) => {
    const w = createShuffleWorker('ts');
    w.onmessage = (ev) => { if (ev.data.type === 'result') { w.terminate(); resolve(ev.data.value); } else if (ev.data.type === 'error') { w.terminate(); reject(new Error(ev.data.message)); } };
    w.onerror = (ev) => reject(new Error(ev.message));
    w.postMessage(req);
  });
}

/** Times `reps` alignments of one scenario. */
async function benchAlign(name: string, req: AlignRequest, reps: number): Promise<ScenarioReport> {
  const backend = selectedBackend();
  const runs: number[] = [];
  let checksum = '';
  let rust: ScenarioReport['rust'];
  for (let i = 0; i < reps; i++) {
    await sleep(400); // let garbage collection and the previous result's memory settle
    const t0 = performance.now();
    let result: AlignResult;
    let timings: RustTimings | undefined;
    let frameBytes = 0;
    if (backend === 'rust') {
      const o = await rustAlign(req);
      ({ result, timings, frameBytes } = o);
    } else {
      result = await tsAlign(req);
    }
    const ms = performance.now() - t0;
    runs.push(round(ms));
    if (i === 0) checksum = alignChecksum(result);
    if (timings !== undefined) rust = { fillMs: round(timings.fillMs), tracebackMs: round(timings.tracebackMs), transferAndDecodeMs: round(ms - timings.fillMs - timings.tracebackMs), frameMB: round(frameBytes / 1048576) };
  }
  return { name, backend, reps, runsMs: runs, minMs: Math.min(...runs), medianMs: median(runs), checksum, ...(rust === undefined ? {} : { rust }) };
}

/** Runs one request on a TypeScript worker and resolves with its result. */
function tsRun<R>(worker: JobWorker<R>, req: unknown): Promise<R> {
  return new Promise((resolve, reject) => {
    worker.onmessage = (ev) => { if (ev.data.type === 'result') { worker.terminate(); resolve(ev.data.value); } else if (ev.data.type === 'error') { worker.terminate(); reject(new Error(ev.data.message)); } };
    worker.onerror = (ev) => reject(new Error(ev.message));
    worker.postMessage(req);
  });
}

/** Times `reps` runs of a generic job; `checksum` fingerprints the first result. */
async function benchJob<R>(name: string, reps: number, run: () => Promise<R>, checksum: (r: R) => string): Promise<ScenarioReport> {
  const backend = selectedBackend();
  const runs: number[] = [];
  let sum = '';
  for (let i = 0; i < reps; i++) {
    await sleep(300);
    const t0 = performance.now();
    const r = await run();
    runs.push(round(performance.now() - t0));
    if (i === 0) sum = checksum(r);
  }
  return { name, backend, reps, runsMs: runs, minMs: Math.min(...runs), medianMs: median(runs), checksum: sum };
}

const matrixChecksum = (m: DistanceMatrix): string => `${m.n}:${hashTyped(m.values)}:${hashTyped(m.status)}:${hashTyped(m.compared)}`;
const bootstrapChecksum = (r: BootstrapResult): string => `${r.supports.length}:${fnv1a32(new TextEncoder().encode(r.supports.map((s) => s.count).join(',')))}:${r.failedReplicates}:${r.replicates}`;

/** Times `reps` shuffle tests. */
async function benchShuffle(name: string, req: ShuffleRequest, reps: number): Promise<ScenarioReport> {
  const backend = selectedBackend();
  const runs: number[] = [];
  let checksum = '';
  for (let i = 0; i < reps; i++) {
    await sleep(300);
    const t0 = performance.now();
    const r = backend === 'rust' ? await rustShuffle(req) : await tsShuffle(req);
    runs.push(round(performance.now() - t0));
    if (i === 0) checksum = `${r.realScore}:${hashTyped(r.scores)}:${bitsHex(r.mean)}:${bitsHex(r.sd)}:${bitsHex(r.pValue)}`;
  }
  return { name, backend, reps, runsMs: runs, minMs: Math.min(...runs), medianMs: median(runs), checksum };
}

/** Runs every scenario for the selected backend. */
export async function runBench(): Promise<{ backend: string; scenarios: ScenarioReport[] }> {
  const scenarios: ScenarioReport[] = [];
  const only = (window as unknown as Record<string, unknown>)['__SEQUENCESCOPE_BENCH_ONLY__']; // set by the app when one scenario was asked for
  const wanted = (key: string): boolean => only === undefined || only === key;
  if (wanted('small')) scenarios.push(await benchAlign('small: 200 x 200 DNA, affine, global', SCENARIOS.small(), 7));
  if (wanted('medium')) scenarios.push(await benchAlign('medium: 1000 x 1000 protein BLOSUM62, affine, global', SCENARIOS.medium(), 5));
  if (wanted('largestDnaLinear')) scenarios.push(await benchAlign('largest: 5000 x 5000 DNA, linear, global', SCENARIOS.largestDnaLinear(), 3));
  if (wanted('largestProteinAffine')) scenarios.push(await benchAlign('largest: 5000 x 5000 protein BLOSUM62, affine, global', SCENARIOS.largestProteinAffine(), 3));
  if (wanted('distancesUnaligned')) {
    const req: DistancesRequest = SCENARIOS.distancesUnaligned();
    scenarios.push(await benchJob('distance matrix: 30 DNA sequences x 400, every pair aligned (435 alignments)', 3, () => (selectedBackend() === 'rust' ? rustDistances(req) : tsRun(createDistancesWorker('ts'), req)), matrixChecksum));
  }
  if (wanted('bootstrapSmall')) {
    const req: BootstrapRequest = SCENARIOS.bootstrapSmall();
    scenarios.push(await benchJob('bootstrap: 100 replicates, 10 x 1144 DNA, NJ', 3, () => (selectedBackend() === 'rust' ? rustBootstrap(req) : tsRun(createBootstrapWorker('ts'), req)), bootstrapChecksum));
  }
  if (wanted('bootstrapLarge')) {
    const req: BootstrapRequest = SCENARIOS.bootstrapLarge();
    scenarios.push(await benchJob('bootstrap: 100 replicates, 50 x 3000 DNA, NJ', 3, () => (selectedBackend() === 'rust' ? rustBootstrap(req) : tsRun(createBootstrapWorker('ts'), req)), bootstrapChecksum));
  }
  if (wanted('shuffle')) scenarios.push(await benchShuffle('shuffle test: 1000 shuffles of 300 x 300 DNA, local, affine', SCENARIOS.shuffle(), 3));
  return { backend: selectedBackend(), scenarios };
}
